/**
 *
 * BreadcrumbEllipsis is a component that displays an ellipsis indicator for collapsed breadcrumb items.
 *
 * [Live Demo](https://www.primereact.org/breadcrumb/)
 *
 * @module BreadcrumbEllipsis
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { BreadcrumbRootInstance } from './BreadcrumbRoot.types';
/**
 * Defines passthrough(pt) options type in BreadcrumbEllipsis component.
 */
export type BreadcrumbEllipsisPassThroughType<E> = PassThroughType<BreadcrumbEllipsisInstance, E>;
/**
 * Defines passthrough(pt) options of BreadcrumbEllipsis component.
 */
export interface BreadcrumbEllipsisPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: BreadcrumbEllipsisPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in BreadcrumbEllipsis component.
 */
export interface BreadcrumbEllipsisProps extends BaseComponentProps<BreadcrumbEllipsisInstance, unknown, BreadcrumbEllipsisPassThrough> {
}
/**
 * Defines valid state in BreadcrumbEllipsis component.
 */
export interface BreadcrumbEllipsisState {
}
/**
 * Defines the methods and properties exposed by BreadcrumbEllipsis component.
 */
export interface BreadcrumbEllipsisExposes {
    /**
     * Instance of the Breadcrumb component.
     */
    breadcrumb: BreadcrumbRootInstance | undefined | null;
}
/**
 * Instance of BreadcrumbEllipsis component.
 */
export type BreadcrumbEllipsisInstance = ComponentInstance<BreadcrumbEllipsisProps, BreadcrumbEllipsisState, BreadcrumbEllipsisExposes>;
